		const tier = model.includes("pro") ? "pro" : "flash";
		const existingWslEnv = process.env.WSLENV || "";
		const env = {
			WSLENV: ["ANTIGRAVITY_LS_ADDRESS", "ANTIGRAVITY_CSRF_TOKEN", "ANTIGRAVITY_PROJECT_ID", existingWslEnv]
				.filter(Boolean).join(":"),
